overrides.style:
Menu, Dropdown, Popup, Dialog { border-radius: 20px; border: 1px solid var(--accent-soft); }
Sheet { border-radius: 26px 26px 0 0; border: 1px solid var(--accent-soft); }
SearchField#chats, SearchField#icons, TextField, Composer::field { border-radius: 18px; }
Fab { border-radius: 13px; }
IconTile[icon="theme"], IconTile[icon="storefront"] { border-radius: 13px; background: var(--accent-soft); color: var(--ink); }
